SELECT 'batch_016_bc83cf23_wav_08' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-1dd661f9659f4669ba92d344dbb67f38','sm-c92fa5ec76c8405d9c7cec39c7e97587','sm-cc2b8a2847e94a7586e169984ce00b4d','sm-upload-10cb9874-55d','sm-upload-23889318-5b0','sm-upload-a2d38eb8-164','sm-upload-c011a487-1d5','sm-upload-ecbc0416-dfd') AND album_id='al-d93c526c9fd2f47003248e5ebc83cf23') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-1dd661f9659f4669ba92d344dbb67f38','sm-c92fa5ec76c8405d9c7cec39c7e97587','sm-cc2b8a2847e94a7586e169984ce00b4d','sm-upload-10cb9874-55d','sm-upload-23889318-5b0','sm-upload-a2d38eb8-164','sm-upload-c011a487-1d5','sm-upload-ecbc0416-dfd') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-d93c526c9fd2f47003248e5ebc83cf23' AND name='人造树的幽灵') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-d93c526c9fd2f47003248e5ebc83cf23') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-d93c526c9fd2f47003248e5ebc83cf23') AS calculated_size;
